public interface DataSink {
    void writeData(ByteBuffer src) throws DataTransferException;
}

public class NioFileSink implements DataSink {
    private final FileChannel fileChannel;

    public NioFileSink(Path path) throws IOException {
        this.fileChannel = FileChannel.open(path, StandardOpenOption.WRITE, StandardOpenOption.CREATE);
    }

    @Override
    public void writeData(ByteBuffer src) throws DataTransferException {
        try {
            while (src.hasRemaining()) {
                fileChannel.write(src);
            }
        } catch (IOException e) {
            throw new DataTransferException("Failed to write buffer to disk via NIO", e);
        }
    }
}
